function input(key,name,type='text',attrs='',optional=false){const label=t(key)+(optional?` (${t('optional')})`:'');return `<label for="f-${name}">${label}<input id="f-${name}" data-label="${key}" name="${name}" type="${type}" ${attrs}></label>`;}
function select(key,name,options){return `<label for="f-${name}">${t(key)}<select id="f-${name}" name="${name}" data-label="${key}">${options}</select></label>`;}
function options(items,value,blank=false){return (blank?`<option value="">${t('choose')}</option>`:'')+items.map(x=>`<option value="${x.id}" ${Number(value)===x.id?'selected':''}>${esc(x.name)}</option>`).join('');}
function notes(){return `<label for="f-notes">${t('notes')} (${t('optional')})<textarea id="f-notes" name="notes" data-label="notes" maxlength="1000"></textarea></label>`;}
function modal(title,hint,content,submit,save){
 const d=$('#modal');d.innerHTML=`<form id="modal-form" novalidate><div class="modal-head"><div><h2 id="dialog-title">${title}</h2><p>${hint}</p></div><button type="button" class="icon-btn" data-action="close" aria-label="${t('close')}">${icon('close')}</button></div><div class="modal-body">${content}<p class="form-error" role="alert"></p></div><div class="modal-footer"><button type="button" class="btn secondary" data-action="close">${t('close')}</button>${submit?`<button class="btn primary" type="submit">${icon('check')}${submit}</button>`:''}</div></form>`;d.setAttribute('aria-labelledby','dialog-title');if(!d.open)d.showModal();
 $('#modal-form').onsubmit=async e=>{e.preventDefault();if(!save)return;const f=e.target;for(const el of f.elements){if(el.willValidate&&!el.checkValidity()){f.querySelector('.form-error').textContent=t(el.validity.valueMissing?'error_required':'error_invalid_field',{field:t(el.dataset.label||'quantity')});el.focus();return;}}const b=f.querySelector('button[type="submit"]');if(b.disabled)return;b.disabled=true;const previous=b.innerHTML;b.textContent=t('saving');f.querySelector('.form-error').textContent='';try{await save(Object.fromEntries(new FormData(f)));d.close();toast(t('saved'));await start();}catch(err){if(d.open)f.querySelector('.form-error').textContent=err.message;else toast(err.message);}finally{b.disabled=false;b.innerHTML=previous;}};
}
