function productForm(existing=null){
 let image=existing?undefined:'',pending=Promise.resolve(),revision=0;
 modal(t(existing?'edit_product':'add_product'),t(existing?'edit_product_hint':'product_hint'),`${input('device_name','name','text',`required maxlength="200" placeholder="${t('device_placeholder')}"`)}${input('default_price','price','number','required min="0" max="1000000" step="0.01" placeholder="0.00"')}<label for="product-file">${t('product_image')} (${t('optional')})<input id="product-file" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="field-help">${t('image_hint')}</p><div id="photo-preview" class="photo-preview" hidden><img alt="${t('product_image')}"><button type="button" class="text-btn" id="remove-photo">${t('remove_image')}</button></div><p id="photo-status" class="field-help" role="status"></p>`,t('save'),async d=>{await pending;await api(existing?`products/${existing.id}/edit`:'products',{name:d.name,price_cents:Math.round(Number(d.price)*100),image});});
 const file=$('#product-file'),preview=$('#photo-preview'),status=$('#photo-status');
 if(existing){const el=$('#modal-form').elements;el.name.value=existing.name;el.price.value=(existing.price_cents/100).toFixed(2);if(existing.has_image){preview.hidden=false;preview.querySelector('img').src=`/api/products/${existing.id}/image?v=${Date.now()}`;}}
 $('#remove-photo').onclick=()=>{revision++;image='';file.value='';preview.hidden=true;status.textContent='';pending=Promise.resolve();};
 file.onchange=()=>{const current=++revision,selected=file.files[0];image='';preview.hidden=true;if(!selected){status.textContent='';return;}
  status.textContent=t('image_processing');
  pending=(async()=>{if(selected.size>10*1024*1024)throw new Error(t('error_image_large'));if(!['image/jpeg','image/png','image/webp'].includes(selected.type))throw new Error(t('error_invalid_image'));
   const url=URL.createObjectURL(selected);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,640/img.width,640/img.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let result=canvas.toDataURL('image/jpeg',.82);if(result.length>260000)result=canvas.toDataURL('image/jpeg',.55);if(result.length>260000)throw new Error(t('error_invalid_image'));if(current!==revision)return;image=result;preview.querySelector('img').src=result;preview.querySelector('img').hidden=false;preview.hidden=false;status.textContent='';}finally{URL.revokeObjectURL(url);}
  })().catch(e=>{if(current===revision){file.value='';image='';preview.hidden=false;preview.querySelector('img').hidden=true;status.textContent=e.message.startsWith('The ')||/[\u0600-\u06ff]/.test(e.message)?e.message:t('error_invalid_image');}throw e;});pending.catch(()=>{});
 };
}
