 const f=$('#modal-form'),el=f.elements;customerSuggestions(f);el.technician_id.required=true;el.source.required=true;
 const update=()=>{const count=totalStock(Number(el.product_id.value),Number(el.warehouse_id.value))+((existing&&!existing.cancelled_at&&existing.product_id===Number(el.product_id.value)&&existing.warehouse_id===Number(el.warehouse_id.value))?existing.quantity:0);$('#stock-hint').textContent=t('stock_at',{count:num(count)});el.quantity.max=existing?.cancelled_at?1000000:count;$('#sale-total').innerHTML=money(Math.round(Number(el.price.value)*100)*Number(el.quantity.value));$('#grand-total').innerHTML=money(Math.round(Number(el.price.value)*100)*Number(el.quantity.value)+Math.round(Number(el.installation_fee.value||0)*100)+Math.round(Number(el.shipping_fee.value||0)*100)+(el.has_sim.checked?500:0));};
 el.product_id.onchange=()=>{const product=state.products.find(p=>p.id===Number(el.product_id.value));$('#sale-photo').innerHTML=product.has_image?productPhoto(product):'';el.price.value=(state.products.find(p=>p.id===Number(el.product_id.value)).price_cents/100).toFixed(2);update();};
 el.technician_id.onchange=()=>{const self=el.technician_id.value==='none';el.installation_fee.disabled=self;if(self)el.installation_fee.value='0';$('#tech-warehouse-hint').hidden=true;update();};
 el.warehouse_id.onchange=()=>{$('#tech-warehouse-hint').hidden=true;update();};el.price.oninput=el.quantity.oninput=el.installation_fee.oninput=el.shipping_fee.oninput=update;
 el.has_sim.onchange=()=>{$('#sim-fields').hidden=!el.has_sim.checked;el.sim_code.required=el.has_sim.checked;el.sim_code.disabled=!el.has_sim.checked;update();};
