function detail(id){const s=saleData?.items.find(x=>x.id===id);if(!s)return;modal(t('sale_number',{id:String(id).padStart(4,'0')}),s.cancelled_at?t('cancelled_hint'):s.sold_on,`<dl class="detail-grid">${[['responsible',s.created_by_name||t('legacy_record')],['device',s.product],['warehouse',s.warehouse],['governorate',provinceName(s.governorate)||'—'],['date',s.sold_on],['quantity',s.quantity],['customer',s.customer||'—'],['phone',s.phone],['source',sourceName(s.source)],['technician',s.technician||t('without_technician')],['address',s.address],['notes',s.notes||'—'],['sim_code',s.sim_code||t('no_sim')]].map(([key,value])=>`<div><dt>${t(key)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><div class="fee-total"><span>${t('unit_price')}</span><strong>${money(s.price_cents)}</strong></div><div class="sale-total"><span>${t('device_total')}</span><strong>${money(s.quantity*s.price_cents)}</strong></div><div class="fee-total"><span>${t('installation_fees')}</span><strong>${money(s.installation_fee_cents)}</strong></div><div class="fee-total"><span>${t('shipping_fees')}</span><strong>${money(s.shipping_fee_cents)}</strong></div><div class="fee-total"><span>${t('sim_fee')}</span><strong>${money(s.sim_code?500:0)}</strong></div><div class="sale-total"><span>${t('grand_total')}</span><strong>${money(s.quantity*s.price_cents+s.installation_fee_cents+s.shipping_fee_cents+(s.sim_code?500:0))}</strong></div><button type="button" class="btn secondary full" data-edit="${id}">${t('edit_sale')}</button>${!s.cancelled_at?`<button type="button" class="text-btn danger" data-cancel="${id}">${t('cancel_sale_restore')}</button>`:''}`,null);}
async function init(){setDocument();$('#app').innerHTML=`<div class="boot">${t('loading')}</div>`;try{await api('auth/me');await start();}catch(e){if($('#login-form'))return;$('#app').innerHTML=`<main class="boot"><p>${esc(e.message)}</p>${button('retry','retry','secondary','arrow')}</main>`;}}

