function loginScreen(){setDocument();$('#app').innerHTML=`<main class="login-page"><section class="login-card panel"><img src="/favicon.svg" alt="" width="52" height="52"><h1>${t('brand')}</h1><p>${t('login_hint')}</p><form id="login-form"><label>${t('username')}<input name="username" autocomplete="username" required maxlength="60" dir="ltr"></label><label>${t('password')}<input name="password" type="password" autocomplete="current-password" required maxlength="200" dir="ltr"></label><p class="form-error" role="alert"></p><button class="btn primary full">${t('login')}</button></form></section></main>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;f.querySelector('.form-error').textContent='';try{await api('auth/login',Object.fromEntries(new FormData(f)));f.reset();await start();}catch(err){f.querySelector('.form-error').textContent=err.message;}finally{b.disabled=false;}};}
const expenseMoney=(amount,currency)=>`<bdi>${num(amount/100)} ${esc(currency)}</bdi>`;
async function renderOdoo(target,version){
 target.innerHTML='<div class="loading">'+t('loading')+'</div>';
 const r=await api('odoo/status');if(version!==renderVersion)return;
 const status=!r.enabled?'sync_disabled':r.first?.error?'sync_failed':r.pending?'sync_pending':'sync_ok';
 target.innerHTML='<section class="panel" style="padding:24px"><h2>'+t(status)+'</h2><p>'+t('sync_explanation')+'</p><dl class="detail-grid"><div><dt>'+t('sync_pending_count')+'</dt><dd>'+num(r.pending)+'</dd></div><div><dt>'+t('sync_delivered_count')+'</dt><dd>'+num(r.delivered)+'</dd></div><div><dt>'+t('sync_last')+'</dt><dd><bdi>'+esc(r.last_success?r.last_success+' UTC':'—')+'</bdi></dd></div></dl>'+(r.first?.error?'<p class="form-error">'+t(r.first.error==='odoo_http_401'?'sync_key_error':'sync_retry_hint')+'</p>':'')+'<a class="btn secondary" href="https://birq.odoo.com/odoo/action-866" target="_blank" rel="noopener noreferrer">'+t('sync_open')+'</a></section>';
 clearTimeout(renderOdoo.timer);renderOdoo.timer=setTimeout(()=>{if(view==='odoo'&&version===renderVersion)renderOdoo(target,version).catch(e=>toast(e.message));},15000);
}
async function renderAccounts(target,version){target.innerHTML=`<div class="loading">${t('loading')}</div>`;const current=view,result=await api(current+'?page='+page);if(version!==renderVersion)return;accountRows=result.items;
 const headers=current==='expenses'?['date','amount','client_details','responsible']:current==='users'?['username','employee_name','role','status','record_details']:['date','responsible','operation','record_details'];
 const rows=result.items.map(r=>current==='expenses'?`<td>${esc(r.paid_on)}</td><td>${expenseMoney(r.amount_cents,r.currency)}</td><td class="wrap-cell">${esc(r.details)}</td><td>${esc(r.actor)}</td>`:current==='users'?`<td>${esc(r.username)}</td><td>${esc(r.name)}</td><td>${t(r.role)}</td><td>${t(r.active?'enabled':'disabled')}</td><td>${r.role==='employee'?`<button class="row-btn" data-user-edit="${r.id}">${t('manage_user')}</button>`:'—'}</td>`:`<td><bdi>${esc(r.created_at)} UTC</bdi></td><td>${esc(r.actor)}</td><td>${esc(operationLabel(r.path))}</td><td><button class="row-btn" data-activity="${r.id}">${t('view_details')}</button></td>`);
 target.innerHTML=`${current==='expenses'?`<div class="expense-totals">${result.totals.map(r=>`<div class="panel"><small>${t('expense_total')}</small><strong>${expenseMoney(r.total,r.currency)}</strong></div>`).join('')}</div>`:''}<section class="panel"><div class="table-scroll"><table><thead><tr>${headers.map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r}</tr>`).join('')}</tbody></table></div>${rows.length?'':`<p class="empty">${t('no_records')}</p>`}${current==='users'?'':pagination(result.total)}</section>`;
}
function operationLabel(path){const bits=path.split('/').filter(Boolean),section={admin:'data_admin',sales:'sales',stock:'inventory',products:'devices',warehouses:'warehouses',technicians:'technicians',clients:'clients',users:'users',expenses:'expenses'}[bits[1]];return (section?t(section):bits[1])+' · '+t(bits.includes('cancel')?'cancelled':bits.includes('transfer')?'transfer_stock':bits.length>2?'operation_update':'operation_add');}
function activityDetail(id){const r=accountRows.find(r=>r.id===id);if(!r)return;let details={};try{details=JSON.parse(r.details);}catch{}modal(t('activity'),esc(r.actor)+' · '+esc(r.created_at)+' UTC',`<h3>${esc(operationLabel(r.path))}</h3><dl class="detail-grid audit-details">${Object.entries(details).map(([k,v])=>{let label;try{label=t(k);}catch{label=k;}return `<div><dt>${esc(label)}</dt><dd>${esc(typeof v==='object'?JSON.stringify(v):v)}</dd></div>`;}).join('')}</dl>`,null);}
function expenseForm(){const request_id=crypto.randomUUID();modal(t('add_expense'),t('expenses_sub'),`${input('amount','amount','number','required min="0.01" max="1000000000" step="0.01"')}${select('expense_currency','currency','<option value="USD">USD</option><option value="SYP">SYP</option>')}${input('date','paid_on','date',`required value="${state.today}" max="${state.today}"`)}<label>${t('client_details')}<textarea name="details" required maxlength="2000" data-label="client_details"></textarea></label>`,t('save'),d=>api('expenses',{amount_cents:Math.round(Number(d.amount)*100),currency:d.currency,details:d.details,paid_on:d.paid_on,request_id}));}
