document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;
 try{
  if(b.dataset.view){view=b.dataset.view;page=1;await render();}
  else if(b.dataset.page){page=Number(b.dataset.page);await render();}
  else if(b.dataset.client){const c=clientData.find(x=>x.id===Number(b.dataset.client));if(c)clientForm(c);}
  else if(b.dataset.category!==undefined){clientCategory=b.dataset.category;page=1;await render();}
  else if(b.dataset.history)await stockHistory(Number(b.dataset.history),Number(b.dataset.historyPage||1));
  else if(b.dataset.location)warehouseDetails(Number(b.dataset.location));
  else if(b.dataset.locationEdit)warehouseEdit(Number(b.dataset.locationEdit));
  else if(b.dataset.techEdit)technicianEdit(Number(b.dataset.techEdit));
  else if(b.dataset.userEdit)editUser(Number(b.dataset.userEdit));
  else if(b.dataset.activity)activityDetail(Number(b.dataset.activity));
  else if(b.dataset.stockMode)stockMode(Number(b.dataset.stockMode));
  else if(b.dataset.transfer)transferForm(Number(b.dataset.transfer));
  else if(b.dataset.stockEdit)stockEdit(Number(b.dataset.stockEdit),Number(b.dataset.stockLocation));
  else if(b.dataset.deviceReport){selectedDevice=Number(b.dataset.deviceReport);page=1;view='device_report';await render();}
  else if(b.dataset.report){reportTech=Number(b.dataset.report);reportFilter={from:'',to:'',kind:'all'};page=1;view='report';await render();}
  else if(b.dataset.customer){selectedCustomer=b.dataset.customer;page=1;view='customer_report';await render();}
  else if(b.dataset.edit){const record=saleData?.items.find(x=>x.id===Number(b.dataset.edit));if(record)saleForm(record);}
  else if(b.dataset.detail)detail(Number(b.dataset.detail));
  else if(b.dataset.product)stockForm(Number(b.dataset.product));
  else if(b.dataset.warehouse)stockForm(null,Number(b.dataset.warehouse));
  else if(b.dataset.access)accessForm(Number(b.dataset.access));
  else if(b.dataset.cancel){const id=Number(b.dataset.cancel);modal(t('cancel_title'),t('cancel_hint'),`<p>${t('cancel_note')}</p>`,t('confirm_cancel'),()=>api(`sales/${id}/cancel`,{}));}
  else switch(b.dataset.action){
   case 'reset-workspace':{const request_id=crypto.randomUUID();modal(t('reset_all'),t('reset_scope'),'<p>'+t('reset_odoo')+'</p><p class="reset-warning">'+t('reset_warning')+'</p>'+input('reset_confirmation','confirmation','text','required autocomplete="off"'),t('reset_all'),async d=>{await api('admin/reset',{request_id,confirmation:d.confirmation});view='overview';selectedDevice=null;reportTech=null;selectedCustomer='';});break;}
   case 'odoo-retry':b.disabled=true;await api('odoo/retry',{});toast(t('sync_requested'));await render();break;
   case 'language':language=language==='ar'?'en':'ar';try{localStorage.setItem('madar-language',language);}catch{}await render();break;
   case 'logout':await api('auth/logout',{});state=null;view='overview';renderVersion++;loginScreen();break;case 'expense':expenseForm();break;case 'user':userForm();break;case 'transfer':transferForm();break;case 'new-client':clientForm();break;case 'export-clients':await exportClients();break;case 'export':await exportRows(b);break;case 'edit-product':productForm(state.products.find(p=>p.id===selectedDevice));break;case 'sale':saleForm();break;case 'product':productForm();break;case 'stock':stockForm();break;case 'warehouse':warehouseForm();break;case 'technician':technicianForm();break;
   case 'report-clear':reportFilter={from:'',to:'',kind:'all'};page=1;await render();break;
   case 'close':$('#modal').close();break;case 'clear':filter={q:'',source:'',from:'',to:'',technician_id:'',governorate:''};page=1;await render();break;case 'retry':await init();break;
  }
 }catch(err){toast(err.message);}
});
init();
